using UnityEngine; using UnityEditor; public class FixRoomBounds { [MenuItem("AnhThoDien/Auto Snap All To Floor")] public static void Fix() { string[] names = {"Bedroom_Shell", "Bed", "Wardrobe", "Fridge", "StudyDesk", "Door"}; foreach(string n in names) { GameObject obj = GameObject.Find(n); if (obj != null) { Renderer[] renderers = obj.GetComponentsInChildren<Renderer>(); if (renderers.Length > 0) { Bounds b = renderers[0].bounds; foreach(Renderer r in renderers) b.Encapsulate(r.bounds); float miny = b.min.y; float offset = -miny; obj.transform.position += new Vector3(0, offset, 0); Debug.Log(n + " snapped to floor. Offset: " + offset); } } } } }
